<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';$db=db();$metrics=[];$metrics['open_tickets']=(int)$db->query("SELECT COUNT(*) FROM support_tickets WHERE status NOT IN ('resolved','closed')")->fetchColumn();$metrics['sla_risks']=(int)$db->query("SELECT COUNT(*) FROM support_tickets WHERE due_at IS NOT NULL AND due_at<NOW() AND status NOT IN ('resolved','closed')")->fetchColumn();$metrics['at_risk_clients']=(int)$db->query("SELECT COUNT(*) FROM client_success_profiles WHERE health IN ('at_risk','critical')")->fetchColumn();foreach($metrics as $metric=>$value){$q=$db->prepare("SELECT * FROM bi_alert_rules WHERE metric=? AND is_active=1");$q->execute([$metric]);foreach($q->fetchAll() as $r){$hit=match($r['operator']){'>'=>(float)$value>(float)$r['threshold'],'>='=>(float)$value>=(float)$r['threshold'],'<'=>(float)$value<(float)$r['threshold'],'<='=>(float)$value<=(float)$r['threshold'],'='=>(float)$value===(float)$r['threshold'],default=>false};if($hit){$q2=$db->prepare('INSERT INTO bi_alert_events(rule_id,metric_value,message) VALUES(?,?,?)');$q2->execute([$r['id'],$value,$r['name'].': '.$metric.'='.$value]);}}}$db->exec('UPDATE automation_rules SET last_run_at=NOW() WHERE is_active=1');echo 'Phase 14 automation completed at '.date('c').PHP_EOL;